"""MotherDuck Flight: build silver_aapl_eod + gold_aapl_daily_returns via dbt.

Runs `dbt build` against the marketstack_test database using dbt-core's
Python API. The dbt project itself lives at dbt/ in the repo (models,
tests, dbt_project.yml, profiles.yml) — PROJECT_FILES below is a generated
embedded copy of it, because a Flight can't import a local package or read
repo files at runtime. Never edit PROJECT_FILES by hand: edit dbt/ and
regenerate this file with generate.py.

This is a local copy of the source currently saved to MotherDuck as the
"marketstack-dbt" Flight. Edit dbt/, run generate.py, then push with:
    update_flight(id=<flight_id>, source_code=...)

Replaces the marketstack-silver and marketstack-gold Flights.
"""
from __future__ import annotations

import pathlib
import tempfile

from dbt.cli.main import dbtRunner

DB = "marketstack_test"

# Generated by generate.py from dbt/ — do not edit by hand.
PROJECT_FILES: dict[str, str] = {'dbt_project.yml': 'name: marketstack\nversion: "1.0.0"\nconfig-version: 2\n\nprofile: marketstack\n\nmodel-paths: ["models"]\ntarget-path: "target"\nclean-targets: ["target", "dbt_packages"]\n\nmodels:\n  marketstack:\n    silver_aapl_eod:\n      +schema: silver\n      +alias: aapl_eod\n      +materialized: incremental\n      +incremental_strategy: delete+insert\n      +unique_key: ["symbol", "trade_date"]\n    gold_aapl_daily_returns:\n      +schema: gold\n      +alias: aapl_daily_returns\n      +materialized: table\n', 'profiles.yml': 'marketstack:\n  target: dev\n  outputs:\n    dev:\n      type: duckdb\n      path: "md:marketstack_test"\n      # Local runs need a MotherDuck token; a Flight\'s `md:` connection is\n      # already authenticated as the Flight\'s identity and needs nothing.\n      extensions:\n        - httpfs\n        - json\n', 'macros/generate_schema_name.sql': '{#\n    Use the custom schema (silver/gold) as-is instead of dbt\'s default\n    "<target_schema>_<custom_schema>" concatenation, so models land in\n    silver.* / gold.* the same way the Flights they replace did.\n#}\n{% macro generate_schema_name(custom_schema_name, node) -%}\n    {%- if custom_schema_name is none -%}\n        {{ target.schema }}\n    {%- else -%}\n        {{ custom_schema_name | trim }}\n    {%- endif -%}\n{%- endmacro %}\n', 'models/sources.yml': 'version: 2\n\nsources:\n  - name: bronze\n    schema: bronze\n    tables:\n      - name: aapl_eod_raw\n        description: >\n          Raw marketstack EOD API pages, appended by the marketstack-bronze\n          Flight. One row per (symbol, trade_date, request_offset) page;\n          silver dedupes to the latest load per (symbol, trade_date).\n        columns:\n          - name: symbol\n            tests: [not_null]\n          - name: trade_date\n            tests: [not_null]\n          - name: raw\n            description: Raw JSON record from the marketstack API, as text.\n          - name: loaded_at\n            description: When this bronze row was appended.\n', 'models/silver_aapl_eod.sql': "-- Dedupe/type Bronze's raw AAPL EOD records into Silver.\n--\n-- Takes the latest bronze row per (symbol, trade_date) (mirrors the\n-- marketstack-silver Flight it replaces) and parses each one's `raw` JSON\n-- blob into typed columns using DuckDB's native JSON operators instead of\n-- a per-row Python json.loads loop.\n--\n-- Materialized as incremental + delete+insert (config in dbt_project.yml,\n-- keyed on symbol/trade_date) so re-running replaces existing rows for\n-- the same key, same effect as the Flight's ON CONFLICT DO UPDATE.\n-- ('merge' isn't valid here: dbt-duckdb only supports it for\n-- iceberg/delta destinations, not plain DuckDB tables.)\n\nwith latest_raw as (\n\n    select *\n    from {{ source('bronze', 'aapl_eod_raw') }}\n    qualify row_number() over (\n        partition by symbol, trade_date order by loaded_at desc\n    ) = 1\n\n)\n\nselect\n    symbol,\n    trade_date,\n    cast(raw::json ->> '$.open' as double) as open,\n    cast(raw::json ->> '$.high' as double) as high,\n    cast(raw::json ->> '$.low' as double) as low,\n    cast(raw::json ->> '$.close' as double) as close,\n    cast(raw::json ->> '$.volume' as double) as volume,\n    cast(raw::json ->> '$.adj_open' as double) as adj_open,\n    cast(raw::json ->> '$.adj_high' as double) as adj_high,\n    cast(raw::json ->> '$.adj_low' as double) as adj_low,\n    cast(raw::json ->> '$.adj_close' as double) as adj_close,\n    cast(raw::json ->> '$.adj_volume' as double) as adj_volume,\n    cast(raw::json ->> '$.split_factor' as double) as split_factor,\n    cast(raw::json ->> '$.dividend' as double) as dividend,\n    raw::json ->> '$.exchange' as exchange,\n    raw::json ->> '$.exchange_code' as exchange_code,\n    raw::json ->> '$.price_currency' as price_currency,\n    now() as silvered_at\nfrom latest_raw\n", 'models/gold_aapl_daily_returns.sql': "-- Recompute the AAPL daily-returns Gold mart from Silver.\n--\n-- Pure SQL recompute (materialized as a table, config in dbt_project.yml)\n-- from silver_aapl_eod — replaces the marketstack-gold Flight's GOLD_SQL.\n\nselect\n    symbol,\n    trade_date,\n    close,\n    lag(close) over (partition by symbol order by trade_date) as prior_close,\n    (close - lag(close) over (partition by symbol order by trade_date))\n        / lag(close) over (partition by symbol order by trade_date) * 100 as daily_return_pct,\n    volume\nfrom {{ ref('silver_aapl_eod') }}\norder by symbol, trade_date\n", 'models/schema.yml': 'version: 2\n\nmodels:\n  - name: silver_aapl_eod\n    description: >\n      Deduped, typed AAPL EOD price data — one row per (symbol, trade_date).\n    columns:\n      - name: symbol\n        tests: [not_null]\n      - name: trade_date\n        tests: [not_null]\n      - name: close\n        description: >\n          Occasionally null upstream (marketstack itself returns\n          close: null for a handful of dates) — warn rather than fail the\n          build, matching the old Flights, which carried these nulls\n          through silently with no test at all.\n        tests:\n          - not_null:\n              config:\n                severity: warn\n\n  - name: gold_aapl_daily_returns\n    description: >\n      Day-over-day AAPL price change, recomputed from silver_aapl_eod.\n    columns:\n      - name: symbol\n        tests: [not_null]\n      - name: trade_date\n        tests: [not_null]\n      - name: close\n        tests:\n          - not_null:\n              config:\n                severity: warn\n', 'tests/silver_unique_symbol_trade_date.sql': "-- Singular test: silver_aapl_eod must have exactly one row per\n-- (symbol, trade_date). Fails (returns rows) if the merge ever produces\n-- duplicates. Avoids depending on dbt_utils so the Flight-embedded copy\n-- of this project stays self-contained (no `dbt deps` network fetch).\n\nselect symbol, trade_date, count(*) as n\nfrom {{ ref('silver_aapl_eod') }}\ngroup by symbol, trade_date\nhaving count(*) > 1\n"}


def write_project(root: pathlib.Path) -> None:
    for relative_path, content in PROJECT_FILES.items():
        path = root / relative_path
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")


def main() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        project_dir = pathlib.Path(tmp)
        write_project(project_dir)

        # A Flight's own `md:` connection is already authenticated as the
        # Flight's identity, same as duckdb.connect("md:") in the other
        # Flights, so profiles.yml needs no token here. If dbt-duckdb ever
        # needs one explicitly, set `motherduck_token` via a Flight secret
        # and reference it in profiles.yml as {{ env_var('motherduck_token') }}.
        result = dbtRunner().invoke(
            [
                "build",
                "--project-dir",
                str(project_dir),
                "--profiles-dir",
                str(project_dir),
            ]
        )

    if not result.success:
        raise RuntimeError(f"dbt build failed: {result.exception or result.result}")

    for run_result in result.result.results:
        print(f"{run_result.node.name}: {run_result.status} ({run_result.execution_time:.1f}s)")
    print("dbt build succeeded.")


if __name__ == "__main__":
    main()
